using Microsoft.AspNetCore.Http.HttpResults;
using ProductsApi.Models;
using ProductsApi.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<IProductService, InMemoryProductService>();

builder.Services.AddOpenApi(options =>
{
    options.AddDocumentTransformer((document, context, ct) =>
    {
        document.Info.Title = "Products API";
        document.Info.Version = "v1";
        document.Info.Description = "A Web API for managing a product catalog.";
        return Task.CompletedTask;
    });
});

var app = builder.Build();

app.MapOpenApi();

if (app.Environment.IsDevelopment())
{
    app.UseSwaggerUI(options => options.SwaggerEndpoint("/openapi/v1.json", "Products API v1"));
}

var products = app.MapGroup("/api/products")
    .WithTags("Products");

products.MapGet("/", (IProductService service) => service.GetAll())
    .WithName("GetAllProducts")
    .WithSummary("List all products")
    .WithDescription("Returns every product currently stored in the catalog.")
    .Produces<IReadOnlyList<Product>>(StatusCodes.Status200OK);

products.MapGet("/{id:int}", Results<Ok<Product>, NotFound> (int id, IProductService service) =>
    {
        var product = service.GetById(id);
        return product is not null
            ? TypedResults.Ok(product)
            : TypedResults.NotFound();
    })
    .WithName("GetProductById")
    .WithSummary("Get a product by ID")
    .WithDescription("Returns a single product matching the supplied identifier, or 404 if not found.")
    .Produces<Product>(StatusCodes.Status200OK)
    .Produces(StatusCodes.Status404NotFound);

products.MapPost("/", Results<Created<Product>, ValidationProblem> (CreateProductRequest request, IProductService service) =>
    {
        if (string.IsNullOrWhiteSpace(request.Name))
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["Name"] = ["Name is required."]
            });
        }

        if (request.Price <= 0)
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["Price"] = ["Price must be greater than zero."]
            });
        }

        var product = service.Create(request);
        return TypedResults.Created($"/api/products/{product.Id}", product);
    })
    .WithName("CreateProduct")
    .WithSummary("Create a new product")
    .WithDescription("Adds a new product to the catalog and returns it with its assigned ID and creation timestamp.")
    .Produces<Product>(StatusCodes.Status201Created)
    .Produces<HttpValidationProblemDetails>(StatusCodes.Status400BadRequest);

app.Run();

